package com.marceloaleixo.centrocirurgico.controller;

import com.marceloaleixo.centrocirurgico.entity.Cirurgia;
import com.marceloaleixo.centrocirurgico.entity.FechamentoFinanceiroCirurgia;
import com.marceloaleixo.centrocirurgico.repository.CirurgiaRepository;
import com.marceloaleixo.centrocirurgico.repository.ConsumoCirurgiaLoteRepository;
import com.marceloaleixo.centrocirurgico.repository.FechamentoFinanceiroCirurgiaRepository;
import com.marceloaleixo.centrocirurgico.entity.AuditoriaFechamentoFinanceiro;
import com.marceloaleixo.centrocirurgico.repository.AuditoriaFechamentoFinanceiroRepository;
import org.springframework.stereotype.Controller;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.OffsetDateTime;

@Controller
@RequestMapping("/financeiro/fechamento-cirurgia")
public class FechamentoFinanceiroCirurgiaController {
 private final CirurgiaRepository cirurgias; private final FechamentoFinanceiroCirurgiaRepository fechamentos; private final ConsumoCirurgiaLoteRepository consumos; private final AuditoriaFechamentoFinanceiroRepository auditorias;
 public FechamentoFinanceiroCirurgiaController(CirurgiaRepository c, FechamentoFinanceiroCirurgiaRepository f, ConsumoCirurgiaLoteRepository x, AuditoriaFechamentoFinanceiroRepository a){cirurgias=c;fechamentos=f;consumos=x;auditorias=a;}
 @GetMapping public String listar(@RequestParam(required=false) Long cirurgiaId, Model model, Authentication authentication){model.addAttribute("usuarioAutenticado", authentication == null ? "" : authentication.getName()); model.addAttribute("podeAprovar", temPerfil(authentication, "ROLE_ADMIN_RH")); model.addAttribute("podeAbrir", temPerfil(authentication, "ROLE_ADMIN_RH") || temPerfil(authentication, "ROLE_RH")); model.addAttribute("cirurgias",cirurgias.findTop200ByOrderByDataCirurgiaDescHoraInicioDesc());model.addAttribute("cirurgiaId",cirurgiaId);model.addAttribute("fechamento",cirurgiaId==null?null:fechamentos.findByCirurgiaId(cirurgiaId).orElse(null));model.addAttribute("temConsumo",cirurgiaId!=null&&!consumos.findByCirurgiaIdOrderByRegistradoEmDesc(cirurgiaId).isEmpty());model.addAttribute("auditorias",cirurgiaId==null?java.util.List.of():auditorias.findTop100ByCirurgiaIdOrderByRegistradoEmDesc(cirurgiaId));return "financeiro/fechamento-cirurgia";}
 @PostMapping("/abrir") @Transactional @PreAuthorize("hasAnyRole('ADMIN_RH', 'RH')") public String abrir(@RequestParam Long cirurgiaId,@RequestParam(required=false) String observacao, Authentication authentication, RedirectAttributes ra){String nome=nomeAutenticado(authentication);Cirurgia cirurgia=cirurgias.findById(cirurgiaId).orElseThrow(()->new IllegalArgumentException("Cirurgia não encontrada."));if(fechamentos.findByCirurgiaId(cirurgiaId).isPresent()){ra.addFlashAttribute("erro","Já existe um fechamento para esta cirurgia.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}FechamentoFinanceiroCirurgia f=new FechamentoFinanceiroCirurgia();f.setCirurgia(cirurgia);f.setStatus("ABERTO");f.setResponsavelAbertura(nome);f.setObservacaoAbertura(limitar(observacao,2000));f.setAbertoEm(OffsetDateTime.now());fechamentos.save(f);registrarAuditoria(cirurgia,nome,"ABERTURA","Conferência financeira aberta. " + (f.getObservacaoAbertura()==null?"":f.getObservacaoAbertura()));ra.addFlashAttribute("sucesso","Conferência financeira aberta.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}
 @PostMapping("/aprovar") @Transactional @PreAuthorize("hasRole('ADMIN_RH')") public String aprovar(@RequestParam Long cirurgiaId,@RequestParam(required=false) String observacao, Authentication authentication, RedirectAttributes ra){String nome=nomeAutenticado(authentication);FechamentoFinanceiroCirurgia f=fechamentos.findByCirurgiaId(cirurgiaId).orElseThrow(()->new IllegalArgumentException("Abra a conferência antes de aprovar."));if("APROVADO".equals(f.getStatus())){ra.addFlashAttribute("erro","Esta cirurgia já está aprovada.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}if(consumos.findByCirurgiaIdOrderByRegistradoEmDesc(cirurgiaId).isEmpty()){ra.addFlashAttribute("erro","Não é possível aprovar sem registros de consumo para conferência.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}f.setStatus("APROVADO");f.setResponsavelAprovacao(nome);f.setObservacaoAprovacao(limitar(observacao,2000));f.setAprovadoEm(OffsetDateTime.now());fechamentos.save(f);registrarAuditoria(f.getCirurgia(),nome,"APROVACAO","Fechamento financeiro aprovado. " + (f.getObservacaoAprovacao()==null?"":f.getObservacaoAprovacao()));ra.addFlashAttribute("sucesso","Fechamento financeiro aprovado.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}
 @PostMapping("/reabrir") @Transactional @PreAuthorize("hasRole('ADMIN_RH')") public String reabrir(@RequestParam Long cirurgiaId,@RequestParam String motivo, Authentication authentication, RedirectAttributes ra){String nome=nomeAutenticado(authentication);if(motivo==null||motivo.isBlank()){ra.addFlashAttribute("erro","Informe o motivo da reabertura.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}FechamentoFinanceiroCirurgia f=fechamentos.findByCirurgiaId(cirurgiaId).orElseThrow(()->new IllegalArgumentException("Fechamento não encontrado."));if(!"APROVADO".equals(f.getStatus())){ra.addFlashAttribute("erro","Somente um fechamento aprovado pode ser reaberto.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}f.setStatus("ABERTO");f.setResponsavelReabertura(nome);f.setMotivoReabertura(limitar(motivo,2000));f.setReabertoEm(OffsetDateTime.now());f.setResponsavelAprovacao(null);f.setAprovadoEm(null);fechamentos.save(f);registrarAuditoria(f.getCirurgia(),nome,"REABERTURA","Fechamento reaberto. Motivo: " + limitar(motivo,2000));ra.addFlashAttribute("sucesso","Fechamento reaberto com justificativa registrada.");return "redirect:/financeiro/fechamento-cirurgia?cirurgiaId="+cirurgiaId;}
 private void registrarAuditoria(Cirurgia cirurgia,String responsavel,String acao,String detalhes){AuditoriaFechamentoFinanceiro a=new AuditoriaFechamentoFinanceiro();a.setCirurgia(cirurgia);a.setResponsavel(responsavel);a.setAcao(acao);a.setDetalhes(detalhes==null||detalhes.isBlank()?acao:detalhes);auditorias.save(a);}
 private String nomeAutenticado(Authentication authentication){if(authentication==null || !authentication.isAuthenticated() || authentication.getName()==null || authentication.getName().isBlank()) throw new IllegalStateException("Não foi possível identificar o usuário autenticado."); return limitar(authentication.getName(),120);}
 private boolean temPerfil(Authentication authentication,String autoridade){return authentication!=null && authentication.getAuthorities().stream().anyMatch(a->autoridade.equals(a.getAuthority()));}
 private String limitar(String s,int n){if(s==null)return null;String t=s.trim();return t.length()>n?t.substring(0,n):t;}
}
